const fs = require("fs");
const path = require("path");
const vm = require("vm");

const projectRoot = process.argv[2];
if (!projectRoot) {
  throw new Error("usage: node playtest-round-50s.js <project-root>");
}

const buildDir = path.join(projectRoot, "build");
const indexPath = path.join(buildDir, "index.html");
const mainPath = path.join(buildDir, "main.js");
const indexHtml = fs.readFileSync(indexPath, "utf8");
const mainJs = fs.readFileSync(mainPath, "utf8");

const scriptRefs = [...indexHtml.matchAll(/<script\s+[^>]*src=["']([^"']+)["'][^>]*>/gi)].map((m) => m[1]);
const missingRefs = scriptRefs.filter((ref) => !fs.existsSync(path.join(buildDir, ref)));
if (!scriptRefs.includes("main.js") || missingRefs.length > 0) {
  throw new Error(`entry refs invalid: refs=${scriptRefs.join(",")} missing=${missingRefs.join(",")}`);
}

function makeElement(id) {
  const classes = new Set();
  return {
    id,
    textContent: "",
    hidden: false,
    style: {},
    attributes: {},
    parentElement: null,
    classList: {
      toggle(name, force) {
        if (force) classes.add(name);
        else classes.delete(name);
      },
      contains(name) {
        return classes.has(name);
      },
    },
    setAttribute(name, value) {
      this.attributes[name] = String(value);
    },
    getAttribute(name) {
      return this.attributes[name];
    },
  };
}

const elements = {
  game: {
    width: 480,
    height: 320,
    getContext() {
      return {
        clearRect() {},
        fillRect() {},
        beginPath() {},
        arc() {},
        fill() {},
        set fillStyle(value) {
          this._fillStyle = value;
        },
        get fillStyle() {
          return this._fillStyle;
        },
      };
    },
  },
  shells: makeElement("shells"),
  tide: makeElement("tide"),
  "tide-status": makeElement("tide-status"),
  "tide-track": makeElement("tide-track"),
  "tide-bar": makeElement("tide-bar"),
  result: makeElement("result"),
  hud: makeElement("hud"),
};
elements["tide-bar"].parentElement = elements["tide-track"];

let nowMs = 0;
let rafCallback = null;
const listeners = {};
const context = {
  console,
  Math,
  clearInterval,
  document: {
    getElementById(id) {
      if (!elements[id]) throw new Error(`missing DOM element ${id}`);
      return elements[id];
    },
  },
  window: {
    addEventListener(type, handler) {
      listeners[type] = handler;
    },
  },
  performance: {
    now() {
      return nowMs;
    },
  },
  requestAnimationFrame(callback) {
    rafCallback = callback;
  },
};
context.global = context;
context.globalThis = context;

vm.createContext(context);
vm.runInContext(mainJs, context, { filename: mainPath });

function snapshot(label) {
  return {
    label,
    tide: elements.tide.textContent,
    aria: elements["tide-track"].getAttribute("aria-valuenow"),
    width: elements["tide-bar"].style.width,
    urgentStatus: elements["tide-status"].classList.contains("urgent"),
    urgentHud: elements.hud.classList.contains("urgent"),
    statusText: elements["tide-status"].textContent,
    resultHidden: elements.result.hidden,
    resultText: elements.result.textContent,
    shells: elements.shells.textContent,
  };
}

function step(frames) {
  for (let i = 0; i < frames; i += 1) {
    if (typeof rafCallback !== "function") throw new Error("missing RAF callback");
    const cb = rafCallback;
    nowMs += 50;
    cb(nowMs);
  }
}

const initial = snapshot("initial");
step(1);
const decrement = snapshot("after-50ms");
step(799);
const pt01 = snapshot("nominal-10s");
step(200);
const settled = snapshot("nominal-0s");
step(5);
const afterSettle = snapshot("after-settle-5-frames");

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

assert(initial.tide === "50", `initial tide expected 50 got ${initial.tide}`);
assert(initial.aria === "50", `initial aria expected 50 got ${initial.aria}`);
assert(decrement.width !== "100%", `countdown width did not decrement: ${decrement.width}`);
assert(pt01.tide === "10", `PT-01 expected HUD 10 got ${pt01.tide}`);
assert(pt01.urgentStatus && pt01.urgentHud, "PT-01 expected urgent on status and HUD");
assert(pt01.statusText === "即将涨潮！", `PT-01 expected urgent text got ${pt01.statusText}`);
assert(settled.tide === "0", `settle expected tide 0 got ${settled.tide}`);
assert(settled.aria === "0", `settle expected aria 0 got ${settled.aria}`);
assert(settled.resultHidden === false, "settle expected result visible");
assert(/^潮汐结算：拾取总数 \d+ 枚$/.test(settled.resultText), `settle text invalid: ${settled.resultText}`);
assert(!settled.resultText.includes("失败"), "settle text must not judge loss");
assert(JSON.stringify(settled) === JSON.stringify({ ...afterSettle, label: "nominal-0s" }), "settlement not idempotent after extra frames");

console.log(`entry refs=${scriptRefs.join(",")} missing=${missingRefs.length}`);
for (const item of [initial, decrement, pt01, settled, afterSettle]) {
  console.log(`${item.label} tide=${item.tide} aria=${item.aria} width=${item.width} urgentStatus=${item.urgentStatus} urgentHud=${item.urgentHud} status=${item.statusText} resultHidden=${item.resultHidden} result=${item.resultText || "-"}`);
}
console.log("PASS round-50s PT-01 regression, settlement, idempotence");
